SELECT CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND((100 * SUM(CASE WHEN country = 'UK' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_uk, MAX(rating) - MIN(rating) AS rating_range, SUM(rating) AS total_rating FROM suppliers WHERE supplier_name LIKE '%Global%' OR city IN ('New York', 'Tokyo', 'Chiang Mai') GROUP BY rating_bucket ORDER BY total_rating, pct_uk DESC;
